((SELECT id FROM m), 'Family Packs', 15, 'Biscuits & Gravy Family Pack', 'Serves 4-6. Served with HomeGrown biscuits, our creamy Scavuzzo''s sausage gravy, pasture-raised scrambled eggs, roasted rosemary potatoes & mini coffeecake muffins.', '60', 60, ARRAY[]::text[], 64),
((SELECT id FROM m), 'Family Packs', 15, 'Salsa Verde Pork Scramble Family Pack', 'Serves 4-6. Pasture-raised scrambled eggs with slow-roasted pork, rosemary potatoes, onion, salsa verde, jack cheese and topped with pico de gallo. Served with HomeGrown pan biscuits, Scavuzzo''s sausage gravy & mini coffeecake muffins.', '60', 60, ARRAY[]::text[], 65),
((SELECT id FROM m), 'Family Packs', 15, 'Jon''s Denver Scramble Family Pack', 'Serves 4-6. Ham, onion, bell pepper, tomato, monterey jack, cheddar & sour cream. Served with roasted rosemary potatoes, HomeGrown pan biscuits, Scavuzzo''s sausage gravy & mini coffeecake muffins.', '60', 60, ARRAY[]::text[], 66),
((SELECT id FROM m), 'Family Packs', 15, 'Gimme the Meats Family Pack', 'Serves 4-6. Crumbled original biscuits baked with pasture-raised eggs, Scavuzzo''s bacon, ham, sausage, mushrooms, onion and red pepper, melted cheddar and Scavuzzo''s sausage gravy. Served with roasted rosemary potatoes & mini coffeecake muffins.', '60', 60, ARRAY[]::text[], 67),
((SELECT id FROM m), 'Family Packs', 15, 'HomeGrown Sammies Family Pack', 'Four sammies: Cuban, Turkey Avocado or the BLTA, sliced in halves. Served with chips, pickle spears and mini coffeecake muffins.', '60', 60, ARRAY[]::text[], 68),
