((SELECT id FROM m), 'Family Packs - Extras', 16, 'Mini Coffeecake Muffins', 'HomeGrown''s original Coffeecake in mini muffins, served with caramel.', 'Six for $3 | 12 for $6 | 18 for $9', 3, ARRAY[]::text[], 70),
